package org.jfree.chart.util;

import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.awt.geom.AffineTransform;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.GeneralPath;
import java.awt.geom.Line2D;
import java.awt.geom.PathIterator;
import java.awt.geom.Point2D;
import java.awt.geom.Rectangle2D;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for ShapeUtilities.equal(GeneralPath, GeneralPath)
 */
public class ShapeUtilities_equal_TriageGen1Test {

    @Test
    public void testEqual_BothNull() {
        assertTrue(ShapeUtilities.equal(null, null));
    }

    @Test
    public void testEqual_P1Null() {
        assertFalse(ShapeUtilities.equal(null, new GeneralPath()));
    }

    @Test
    public void testEqual_P2Null() {
        assertFalse(ShapeUtilities.equal(new GeneralPath(), null));
    }

    @Test
    public void testEqual_DifferentWindingRule() {
        GeneralPath p1 = new GeneralPath(PathIterator.WIND_EVEN_ODD);
        GeneralPath p2 = new GeneralPath(PathIterator.WIND_NON_ZERO);
        assertFalse(ShapeUtilities.equal(p1, p2));
    }

    @Test
    public void testEqual_IdenticalPaths() {
        GeneralPath p1 = new GeneralPath();
        p1.moveTo(0, 0);
        p1.lineTo(10, 10);
        p1.closePath();

        GeneralPath p2 = new GeneralPath();
        p2.moveTo(0, 0);
        p2.lineTo(10, 10);
        p2.closePath();

        assertTrue(ShapeUtilities.equal(p1, p2));
    }

    @Test
    public void testEqual_DifferentSegments() {
        GeneralPath p1 = new GeneralPath();
        p1.moveTo(0, 0);
        p1.lineTo(10, 10);

        GeneralPath p2 = new GeneralPath();
        p2.moveTo(0, 0);
        p2.lineTo(10, 11); // Different coordinate

        assertFalse(ShapeUtilities.equal(p1, p2));
    }

    @Test
    public void testEqual_DifferentSegmentTypes() {
        GeneralPath p1 = new GeneralPath();
        p1.moveTo(0, 0);
        p1.lineTo(10, 10);

        GeneralPath p2 = new GeneralPath();
        p2.moveTo(0, 0);
        p2.quadTo(5, 5, 10, 10); // Line vs Quad

        assertFalse(ShapeUtilities.equal(p1, p2));
    }

    @Test
    public void testEqual_DifferentPathLengths() {
        GeneralPath p1 = new GeneralPath();
        p1.moveTo(0, 0);
        p1.lineTo(10, 10);

        GeneralPath p2 = new GeneralPath();
        p2.moveTo(0, 0);
        p2.lineTo(10, 10);
        p2.lineTo(20, 20); // Extra segment

        // Note: The implementation uses iterator1.isDone() != iterator2.isDone() 
        // inside the loop, but the loop condition is 'done = i1.isDone() && i2.isDone()'.
        // This test checks the branch where one iterator finishes before the other.
        assertFalse(ShapeUtilities.equal(p1, p2));
    }

    @Test
    public void testEqual_EmptyPaths() {
        GeneralPath p1 = new GeneralPath();
        GeneralPath p2 = new GeneralPath();
        assertTrue(ShapeUtilities.equal(p1, p2));
    }
}
